function updateConnectionLabel(){
 const label=$('connection-label'),dot=$('connection-dot');
 if(label)label.textContent=cloudUser?'NUVEM + LOCAL':'LOCAL';
 if(dot)dot.classList.toggle('online',!!cloudUser);
}
async function loadLocalPayload(){
 let apiError=null;
 try{
  const res=await fetch('/api/load',{cache:'no-store'});
  if(res.ok){const data=await res.json();if(data&&data.version===1&&data.state)return {data,source:'computer'};if(data===null)apiError=null;else throw new Error('Formato de salvamento local inválido.');}
  else if(res.status!==404&&res.status!==405)throw new Error('Não foi possível ler o salvamento local.');
 }catch(error){apiError=error}
 try{
  const raw=localStorage.getItem('cf2.save');
  if(raw){const data=JSON.parse(raw);if(data&&data.version===1&&data.state)return {data,source:'browser'};throw new Error('Backup do navegador inválido.')}
 }catch(error){if(error instanceof SyntaxError)throw error}
 if(apiError)throw apiError;
 return {data:null,source:'new'};
}
async function saveLocalPayload(payload){
 try{
  const res=await fetch('/api/save',{method:'POST',headers:{'Content-Type':'application/json'},body:payload});
  if(res.ok){try{localStorage.setItem('cf2.save',payload)}catch{}return 'computador'}
  if(res.status!==404&&res.status!==405)throw new Error('O servidor local recusou o salvamento.');
 }catch(error){
  if(error?.message==='O servidor local recusou o salvamento.')throw error;
 }
 try{localStorage.setItem('cf2.save',payload);return 'navegador'}catch{throw new Error('Não foi possível gravar uma cópia local.')}
}
async function saveCloud(){
 if(!supabaseClient||!cloudUser)return;
 const nextRevision=cloudRevision+1;
 const row={user_id:cloudUser.id,farm_name:state.farmName||'Minha fazenda',state:JSON.parse(JSON.stringify(state)),revision:nextRevision,updated_at:new Date().toISOString()};
 let result;
 if(cloudRevision===0){
  result=await supabaseClient.from('farm_saves').insert(row).select('revision,updated_at').single();
 }else{
  const update={farm_name:row.farm_name,state:row.state,revision:nextRevision,updated_at:row.updated_at};
  result=await supabaseClient.from('farm_saves').update(update).eq('user_id',cloudUser.id).eq('revision',cloudRevision).select('revision,updated_at').maybeSingle();
 }
 if(result.error)throw result.error;
 if(!result.data)throw new Error('A fazenda na nuvem foi alterada em outro dispositivo. Entre novamente para comparar as versões.');
 cloudRevision=Number(result.data.revision)||nextRevision;cloudUpdatedAt=result.data.updated_at||row.updated_at;cloudDirty=false;
}
async function handleAuthSession(session){
 if(!session?.user||!supabaseClient)return;
 if(cloudSyncing)return;
 cloudSyncing=true;cloudUser=session.user;updateConnectionLabel();
 try{
  const {data,error}=await supabaseClient.from('farm_saves').select('state,revision,updated_at').eq('user_id',cloudUser.id).maybeSingle();
  if(error)throw error;
  if(!data){
   cloudRevision=0;await saveCloud();
   $('save-status').textContent='Fazenda enviada para a nuvem';
   notify('Conta conectada. Sua fazenda local foi enviada para a nuvem.');
  }else{
   cloudRevision=Number(data.revision)||1;cloudUpdatedAt=data.updated_at||null;
   const localStamp=Number(state?.updatedAt)||0,cloudStamp=Date.parse(data.updated_at||'')||0;
   let useCloud=!localSaveExists||localStamp<=cloudStamp+1000;
   if(localSaveExists&&localStamp>cloudStamp+1000)useCloud=window.confirm('Encontramos uma fazenda salva na nuvem e outra mais recente neste dispositivo.\\n\\nOK: carregar a fazenda da nuvem.\\nCancelar: manter a fazenda deste dispositivo e enviá-la para a nuvem.');
   if(useCloud){
    const restored=normalize(data.state);if(!restored)throw new Error('A fazenda da nuvem está em um formato inválido.');
    state=restored;dirty=false;cloudDirty=false;refresh();
    const payload=JSON.stringify({version:1,state});await saveLocalPayload(payload);localSaveExists=true;
    $('save-status').textContent='Sincronizado com a nuvem';
    notify('Fazenda carregada da nuvem e salva também neste dispositivo.');
   }else{
    await saveCloud();$('save-status').textContent='Fazenda local enviada para a nuvem';
    notify('Fazenda deste dispositivo enviada para a nuvem.');
   }
  }
 }catch(error){
  console.error('Supabase:',error);cloudDirty=true;$('save-status').textContent='Salvo localmente · nuvem pendente';
  notify('A conta conectou, mas a sincronização falhou: '+(error.message||'verifique a configuração do Supabase.'));
 }finally{
  cloudSyncing=false;updateConnectionLabel();if(currentModal==='account')renderModal();
 }
}
async function authenticate(mode){
 if(!initSupabase())return notify('A conexão de autenticação não carregou. Verifique sua internet e tente novamente.');
 const email=$('auth-email')?.value.trim()||'',password=$('auth-password')?.value||'';
 if(!email||!password)return notify('Informe e-mail e senha.');
 const result=mode==='signup'
  ?await supabaseClient.auth.signUp({email,password,options:{emailRedirectTo:window.location.origin}})
  :await supabaseClient.auth.signInWithPassword({email,password});
 if(result.error)return notify(result.error.message||'Não foi possível autenticar.');
 if(result.data.session){await handleAuthSession(result.data.session);if(currentModal==='account')renderModal();}
 else notify('Cadastro iniciado. Verifique seu e-mail para confirmar a conta antes de entrar.');
}
async function disconnectCloud(){
 if(!supabaseClient)return;
 const {error}=await supabaseClient.auth.signOut();if(error)return notify(error.message||'Não foi possível sair da conta.');
 cloudUser=null;cloudRevision=0;cloudUpdatedAt=null;cloudDirty=false;updateConnectionLabel();notify('Sessão encerrada. Sua fazenda continua salva localmente.');renderModal();
}

let soundEnabled=true,musicEnabled=true;
try{soundEnabled=localStorage.getItem('cf2.sound')!=='off';musicEnabled=localStorage.getItem('cf2.music')!=='off'}catch{}
function ensureAudio(){
 const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)return null;
 if(!audioCtx)audioCtx=new Ctx();if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});
 return audioCtx;
}
function playTone(freq,duration=.12,wave='sine',volume=.045,slide=0){
 const ctx=ensureAudio();if(!ctx)return;
 const osc=ctx.createOscillator(),gain=ctx.createGain(),now=ctx.currentTime;
 osc.type=wave;osc.frequency.setValueAtTime(Math.max(40,freq),now);
 if(slide)osc.frequency.exponentialRampToValueAtTime(Math.max(40,freq+slide),now+duration);
 gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(volume,now+.012);gain.gain.exponentialRampToValueAtTime(.0001,now+duration);
 osc.connect(gain);gain.connect(ctx.destination);osc.start(now);osc.stop(now+duration+.02);
}
function playNoise(duration=.12,volume=.025,frequency=900){
 const ctx=ensureAudio();if(!ctx)return;
 const length=Math.max(1,Math.floor(ctx.sampleRate*duration)),buffer=ctx.createBuffer(1,length,ctx.sampleRate),data=buffer.getChannelData(0);
 for(let i=0;i<length;i++)data[i]=(Math.random()*2-1)*(1-i/length);
 const source=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain(),now=ctx.currentTime;
 source.buffer=buffer;filter.type='bandpass';filter.frequency.value=frequency;filter.Q.value=.7;
 gain.gain.setValueAtTime(volume,now);gain.gain.exponentialRampToValueAtTime(.0001,now+duration);
 source.connect(filter);filter.connect(gain);gain.connect(ctx.destination);source.start(now);source.stop(now+duration);
}
function playSfx(kind){
 if(!soundEnabled)return;ensureAudio();
 const patterns={
  plant:()=>{playTone(520,.09,'triangle',.035,100);setTimeout(()=>playTone(740,.12,'sine',.035,80),75)},
  water:()=>{playNoise(.22,.018,520);playTone(620,.18,'sine',.018,-110)},
  weed:()=>{playNoise(.09,.035,1200);playTone(880,.08,'triangle',.025,-260)},
  pest:()=>{playTone(980,.07,'square',.018,-350);setTimeout(()=>playTone(640,.1,'sine',.025,-170),70)},
  hoe:()=>{playNoise(.12,.035,260);playTone(155,.12,'triangle',.025,-45)},
  fertilizer:()=>{playTone(300,.24,'sine',.035,550);setTimeout(()=>playTone(780,.16,'sine',.025,160),100)},
  harvest:()=>{playTone(523,.15,'sine',.035);setTimeout(()=>playTone(659,.15,'sine',.035),95);setTimeout(()=>playTone(784,.24,'sine',.04),190)}
 };
 (patterns[kind]||(()=>{}))();
}
// Tema campestre mais vivo: melodia em Sol maior, baixo macio e acordes leves.
const FARM_MELODY=[392,494,587,659,587,494,440,494,523,587,659,784,659,587,494,440];
const FARM_BASS=[196,147,165,131];
const FARM_CHORDS=[[392,494,587],[294,370,440],[330,392,494],[262,330,392]];
function startFarmMusic(){
 if(!musicEnabled||musicPlaying)return;const ctx=ensureAudio();if(!ctx)return;musicPlaying=true;musicIndex=0;
 const step=()=>{if(!musicEnabled){musicPlaying=false;return}
  const beat=musicIndex%FARM_MELODY.length,note=FARM_MELODY[beat],bar=Math.floor(beat/4)%FARM_CHORDS.length;
  // Volume reforçado para a música se destacar dos sons ambientes do navegador.
  playTone(note,.23,'triangle',.058);
  if(beat%2===0)playTone(note*2,.12,'sine',.012);
  if(beat%4===0){playTone(FARM_BASS[bar],.38,'sine',.034);FARM_CHORDS[bar].forEach((tone,i)=>setTimeout(()=>playTone(tone,.3,'triangle',.012),i*18))}
  if(beat%8===7){setTimeout(()=>playTone(1175,.08,'sine',.016,-220),55);setTimeout(()=>playTone(1568,.07,'sine',.014,-260),125)}
  musicIndex++;musicTimer=setTimeout(step,280)
 };
 step();
}
function stopFarmMusic(){if(musicTimer)clearTimeout(musicTimer);musicTimer=null;musicPlaying=false}
function setSoundEnabled(value){soundEnabled=!!value;try{localStorage.setItem('cf2.sound',soundEnabled?'on':'off')}catch{}if(soundEnabled)playTone(660,.1,'sine',.025)}
function setMusicEnabled(value){musicEnabled=!!value;try{localStorage.setItem('cf2.music',musicEnabled?'on':'off')}catch{}if(musicEnabled)startFarmMusic();else stopFarmMusic()}
document.addEventListener('pointerdown',()=>{if(musicEnabled&&!musicPlaying)startFarmMusic()},{once:true});

