 if(bird){aviarySlot=state.animals.filter(a=>isBirdType(a.type)).reduce((max,a)=>Math.max(max,Number.isInteger(a.aviarySlot)?a.aviarySlot:-1),-1)+1;}
 else{const used=new Set(state.animals.filter(a=>a.type!=='cachorro'&&!isBirdType(a.type)).map(a=>a.slot));slot=ANIMAL_SLOTS.findIndex((_,i)=>!used.has(i));if(slot<0)return notify('Não há espaço livre no curral.');}
 state[wallet]-=cfg.price;
 state.animals.push({id:`${type}-${Date.now()}-${Math.floor(Math.random()*10000)}`,type,name:cfg.name,slot,aviarySlot,status:'hungry',stage:1,readyAt:0,guardUntil:0});
 remember(`Comprou ${cfg.name} para o ${bird?'viveiro':'curral'}.`);
