function recipeIngredientTotals(recipe){const totals=new Map();for(const [type,id,qty] of recipe.ingredients){const key=`${type}:${id}`,current=totals.get(key);if(current)current.qty+=qty;else totals.set(key,{type,id,qty});}return [...totals.values()]}
function recipeMissing(recipe){return recipeIngredientTotals(recipe).filter(({type,id,qty})=>ingredientCount(type,id)<qty)}
function recipeNeedText(recipe){return recipeIngredientTotals(recipe).map(({type,id,qty})=>`${type==='crop'?CROPS[id]?.icon:type==='meat'?MEAT_PRODUCTS[id]?.icon:type==='fish'?FISH_TYPES[id]?.icon:type==='animal'?ANIMAL_PRODUCTS[id]?.icon:GRILL_SUPPLIES[id]?.icon} ${qty} ${ingredientName(type,id)}`).join(' + ')}
function buyGrillSupply(id){if(writeLocked)return notify('Salvamento protegido.');const cfg=GRILL_SUPPLIES[id];if(!cfg)return;if(state.coins<cfg.price)return notify('Moedas amarelas insuficientes.');state.coins-=cfg.price;state.inventory[id]=(state.inventory[id]||0)+1;remember(`Comprou ${cfg.name} para a churrasqueira.`);markDirty();refresh();notify(`${cfg.name} adicionado aos ingredientes.`)}
function buyTurkeyMeat(){if(writeLocked)return notify('Salvamento protegido.');const price=650;if(state.coins<price)return notify('Moedas amarelas insuficientes para comprar carne de peru.');state.coins-=price;state.meatWarehouse.turkey=(state.meatWarehouse.turkey||0)+1;remember('Comprou 1 porção de carne de peru no fornecedor local offline.');markDirty();refresh();notify('Carne de peru adicionada ao depósito. Este fornecedor local substitui a aquisição social indisponível offline.')}
function butcherAnimal(id){if(writeLocked)return notify('Salvamento protegido.');const i=state.animals.findIndex(a=>a.id===id);if(i<0)return;const a=state.animals[i],source=ANIMAL_MEAT_SOURCE[a.type];if(!source)return notify('Este animal não fornece carne nesta edição.');if(a.type==='porco'?a.status!=='adult':a.status!=='hungry')return notify(a.type==='porco'?'O porco precisa chegar à fase adulta antes do abate.':'Conclua ou recolha a produção antes de abater este animal.');const cfg=MEAT_PRODUCTS[source.meat],yieldCount=source.yield+(ANIMAL_RATIONS[a.type]?Math.max(0,(a.level||1)-1):0);if(!confirm(`Abater ${a.name||ANIMALS[a.type].name}? O animal será removido permanentemente e você receberá ${yieldCount} unidade(s) de ${cfg.name}.`))return;state.meatWarehouse[source.meat]=(state.meatWarehouse[source.meat]||0)+yieldCount;state.animals.splice(i,1);awardXP(5,'manejo da fazenda');remember(`Abateu ${a.name||ANIMALS[a.type].name} e obteve ${yieldCount} ${cfg.name}.`);markDirty();refresh();notify(`${yieldCount} unidade(s) de ${cfg.name} adicionadas ao depósito.`)}
function produceGrillRecipe(id){if(writeLocked)return notify('Salvamento protegido.');if(!state.grill.assembled)return notify('Monte a churrasqueira antes de produzir.');const recipe=GRILL_RECIPES[id];if(!recipe)return;if(state.grill.queue.length>=100)return notify('A fila da churrasqueira atingiu o limite de 100 preparos.');const missing=recipeMissing(recipe);if(missing.length)return notify('Ingredientes insuficientes: '+missing.map(([t,k,q])=>`${q} ${ingredientName(t,k)}`).join(', '));for(const {type,id:key,qty} of recipeIngredientTotals(recipe)){if(type==='crop')state.warehouse[key]-=qty;else if(type==='meat')state.meatWarehouse[key]-=qty;else if(type==='fish')state.fishWarehouse[key]-=qty;else if(type==='sea')state.seaWarehouse[key]-=qty;else if(type==='wood')state.woodWarehouse[key]-=qty;else if(type==='animal')state.animalWarehouse[key]-=qty;else state.inventory[key]-=qty;}const now=Date.now(),last=state.grill.queue.filter(j=>j.readyAt>now).reduce((m,j)=>Math.max(m,j.readyAt),now),startedAt=last,readyAt=startedAt+recipe.minutes*GRILL_TIME_FACTOR*60000;state.grill.queue.push({id:`grill-${now}-${Math.floor(Math.random()*100000)}`,recipe:id,startedAt,readyAt});remember(`Enfileirou ${recipe.name} na churrasqueira.`);markDirty();refresh();notify(`${recipe.name} entrou na fila · preparo em ${formatHours(recipe.minutes*GRILL_TIME_FACTOR/60)}.`)}
function produceKitchenRecipe(id){if(writeLocked)return notify('Salvamento protegido.');const recipe=GRILL_RECIPES[id];if(!recipe?.kitchenOnly)return;if(state.kitchen.queue.length>=3)return notify('A cozinha comporta até 3 receitas por vez.');if(state.kitchen.queue.some(j=>j.recipe===id))return notify('Esta receita já está em preparo.');const missing=recipeMissing(recipe);if(missing.length)return notify('Ingredientes insuficientes: '+missing.map(([t,k,q])=>`${q} ${ingredientName(t,k)}`).join(', '));for(const {type,id:key,qty} of recipeIngredientTotals(recipe)){if(type==='crop')state.warehouse[key]-=qty;else if(type==='meat')state.meatWarehouse[key]-=qty;else if(type==='fish')state.fishWarehouse[key]-=qty;else if(type==='sea')state.seaWarehouse[key]-=qty;else if(type==='wood')state.woodWarehouse[key]-=qty;else if(type==='animal')state.animalWarehouse[key]-=qty;else state.inventory[key]-=qty;}const now=Date.now(),readyAt=now+recipe.minutes*KITCHEN_TIME_FACTOR*60000;state.kitchen.queue.push({id:`kitchen-${now}-${Math.floor(Math.random()*100000)}`,recipe:id,startedAt:now,readyAt});remember(`Iniciou ${recipe.name} na cozinha.`);markDirty();refresh();notify(`${recipe.name} iniciado · preparo em ${formatHours(recipe.minutes*KITCHEN_TIME_FACTOR/60)}.`)}
function collectKitchen(){if(writeLocked)return notify('Salvamento protegido.');const now=Date.now(),ready=state.kitchen.queue.filter(j=>j.readyAt<=now);if(!ready.length)return notify('Ainda não há pratos prontos para recolher.');let total=0,xp=0;for(const job of ready){const r=GRILL_RECIPES[job.recipe];state.processedWarehouse[job.recipe]=(state.processedWarehouse[job.recipe]||0)+r.yield;total+=r.yield;xp+=r.xp;}state.kitchen.queue=state.kitchen.queue.filter(j=>j.readyAt>now);awardXP(xp,'cozinha da fazenda');remember(`Recolheu ${ready.length} preparo(s) da cozinha (${total} pratos).`);markDirty();refresh();notify(`${total} prato(s) recolhidos da cozinha · +${xp} XP.`)}
function collectGrill(){if(writeLocked)return notify('Salvamento protegido.');const now=Date.now(),ready=state.grill.queue.filter(j=>j.readyAt<=now);if(!ready.length)return notify('Ainda não há pratos prontos para recolher.');let total=0,xp=0;for(const job of ready){const r=GRILL_RECIPES[job.recipe];state.processedWarehouse[job.recipe]=(state.processedWarehouse[job.recipe]||0)+r.yield;total+=r.yield;xp+=r.xp;}state.grill.queue=state.grill.queue.filter(j=>j.readyAt>now);awardXP(xp,'churrasqueira');remember(`Recolheu ${ready.length} preparo(s) da churrasqueira (${total} pratos).`);markDirty();refresh();notify(`${total} prato(s) recolhidos · +${xp} XP.`)}
function toggleMeatLock(id){if(writeLocked)return notify('Salvamento protegido.');if(!MEAT_PRODUCTS[id])return;state.meatLocks[id]=!state.meatLocks[id];remember(`${state.meatLocks[id]?'Bloqueou':'Desbloqueou'} a venda de ${MEAT_PRODUCTS[id].name}.`);markDirty();refresh()}
function sellMeat(id){if(writeLocked)return notify('Salvamento protegido.');const cfg=MEAT_PRODUCTS[id],qty=state.meatWarehouse[id]||0;if(!cfg||qty<=0)return;if(state.meatLocks[id])return notify('Este ingrediente está bloqueado contra venda acidental. Desbloqueie-o no depósito.');const total=saleWithPopularity(qty*cfg.unitPrice);state.coins+=total;state.meatWarehouse[id]=0;remember(`Vendeu ${qty} ${cfg.name}.`);markDirty();refresh();notify(`${cfg.name} vendidos: +${fmt(total)} moedas.`)}
function toggleProcessedLock(id){if(writeLocked)return notify('Salvamento protegido.');if(!GRILL_RECIPES[id])return;state.processedLocks[id]=!state.processedLocks[id];remember(`${state.processedLocks[id]?'Bloqueou':'Desbloqueou'} a venda de ${GRILL_RECIPES[id].name}.`);markDirty();refresh()}
function sellProcessed(id){if(writeLocked)return notify('Salvamento protegido.');const recipe=GRILL_RECIPES[id],qty=state.processedWarehouse[id]||0;if(!recipe||qty<=0)return;if(state.processedLocks[id])return notify('Este prato está bloqueado contra venda acidental. Desbloqueie-o no depósito.');const total=saleWithPopularity(qty*recipe.salePrice);state.coins+=total;state.processedWarehouse[id]=0;remember(`Vendeu ${qty} ${recipe.name} com bônus de popularidade.`);markDirty();refresh();notify(`${recipe.name} vendido(s): +${fmt(total)} moedas.`)}
function applyFarmTheme(id){if(writeLocked)return notify('Salvamento protegido.');if(!FARM_THEMES[id])return;if(id!=='classic'&&!(state.farmThemeExpiries?.[id]>Date.now()))return notify('Este tema não está disponível. Adquira-o primeiro.');state.farmTheme=id;remember('Aplicou o tema de fazenda: '+FARM_THEMES[id].name+'.');markDirty();renderFarmAddons();refresh();notify('Tema '+FARM_THEMES[id].name+' aplicado!')}
function buyFarmTheme(id){if(writeLocked)return notify('Salvamento protegido.');const t=FARM_THEMES[id];if(!t||id==='classic')return;if(state.farmThemeExpiries?.[id]>Date.now())return applyFarmTheme(id);const wallet=t.currency==='greenCoins'?'greenCoins':'coins';if(state[wallet]<t.price)return notify(t.currency==='greenCoins'?'Moedas verdes insuficientes.':'Moedas amarelas insuficientes.');state[wallet]-=t.price;const now=Date.now(),base=Math.max(now,state.farmThemeExpiries?.[id]||0);state.farmThemeExpiries[id]=base+(t.days||30)*24*HOUR;if(t.xp)awardXP(t.xp,'compra de tema');state.farmTheme=id;remember('Adquiriu o tema de fazenda: '+t.name+'.');markDirty();renderFarmAddons();refresh();notify(t.name+' adquirido e aplicado por '+(t.days||30)+' dias.')}
function expireFarmTheme(){if(!state||!state.farmTheme||state.farmTheme==='classic')return;const until=state.farmThemeExpiries?.[state.farmTheme]||0;if(until>Date.now())return;const old=FARM_THEMES[state.farmTheme]?.name||'Tema';state.farmTheme='classic';remember('O tema '+old+' expirou; a fazenda voltou ao visual clássico.');markDirty();renderFarmAddons()}
function buyDecoration(id){if(writeLocked)return notify('Salvamento protegido.');const d=DECORATIONS[id];if(!d)return;if(d.obtainOnly)return notify(d.obtainNote||'Este item é obtido por uma recompensa histórica.');const wallet=d.currency==='greenCoins'?'greenCoins':'coins';if(state[wallet]<d.price)return notify(d.currency==='greenCoins'?'Moedas verdes insuficientes.':'Moedas amarelas insuficientes.');state[wallet]-=d.price;state.decorInventory[id]=(state.decorInventory[id]||0)+1;awardXP(d.xp||0,'compra de decoração');remember('Comprou decoração: '+d.name+'.');markDirty();refresh();notify(d.name+' adicionada aos seus itens.')}
const DECORATION_SLOTS=[[600,140],[-650,220],[1800,170],[2050,690],[-650,850],[2500,160],[2800,650],[3300,400],[-1120,160],[4200,170],[4200,1010],[1900,1030]];
function placeDecoration(id){if(writeLocked)return notify('Salvamento protegido.');if(!DECORATIONS[id]||(state.decorInventory[id]||0)<=0)return;const used=new Set(state.placedDecorations.map(d=>d.slot));const slot=DECORATION_SLOTS.findIndex((_,i)=>!used.has(i));if(slot<0)return notify('Todos os espaços seguros de decoração estão ocupados.');state.decorInventory[id]--;state.placedDecorations.push({id,slot,installedAt:Date.now(),expiresAt:Date.now()+30*24*HOUR});remember('Instalou '+DECORATIONS[id].name+'.');markDirty();renderFarmAddons();refresh();notify(DECORATIONS[id].name+' instalada na fazenda.')}
function removeDecoration(slot){expireDecorations();const i=state.placedDecorations.findIndex(d=>d.slot===Number(slot));if(i<0)return;const d=state.placedDecorations.splice(i,1)[0];state.decorInventory[d.id]=(state.decorInventory[d.id]||0)+1;remember('Guardou '+DECORATIONS[d.id].name+'.');markDirty();renderFarmAddons();refresh();notify('Decoração guardada nos itens.')}
function expireDecorations(){if(!state||!Array.isArray(state.placedDecorations))return;const now=Date.now(),expired=state.placedDecorations.filter(d=>Number.isFinite(d.expiresAt)&&d.expiresAt<=now);if(!expired.length)return;state.placedDecorations=state.placedDecorations.filter(d=>!Number.isFinite(d.expiresAt)||d.expiresAt>now);remember(`${expired.length} decoração(ões) expiraram após 30 dias.`);markDirty();renderFarmAddons();notify('Uma decoração da fazenda expirou.')}
